    {canRequest&&requestPlan&&<div className="license-modal-backdrop" role="presentation" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setRequestPlan(null);}}><section className="license-modal" role="dialog" aria-modal="true" aria-label="Request license change"><button className="license-close" type="button" onClick={()=>setRequestPlan(null)}>×</button><h3>Request {requestPlan==='annual'?'Annual':'Lifetime'} License</h3><p>Current: {state?.license?.plan||'Not Assigned'} · Configured price: {rupees(requestPlan==='annual'?pricing.annualPaise:clientLifetimeDue)}{requestPlan==='lifetime'&&clientCredit>0&&` (includes ${rupees(clientCredit)} Annual payment credit)`}. Payment is reviewed by the Master Admin.</p><p>{pricing.paymentInstructions}</p>{paymentDetails.accountNumber&&<p>Payee: {paymentDetails.accountHolder} · {paymentDetails.bankName} · A/C {paymentDetails.accountNumber} · IFSC {paymentDetails.ifsc}</p>}{paymentDetails.upiId&&<p>UPI: {paymentDetails.upiId}</p>}<label>Amount paid (INR)<input type="number" min="0" step="0.01" value={paymentForm.amount} onChange={e=>setPaymentForm({...paymentForm,amount:e.target.value})}/></label><label>Payment date<input type="date" max={indiaDate()} value={paymentForm.date} onChange={e=>setPaymentForm({...paymentForm,date:e.target.value})}/></label><label>Transaction ID / UTR<input value={paymentForm.transactionId} maxLength={64} onChange={e=>setPaymentForm({...paymentForm,transactionId:e.target.value})}/></label><button type="button" disabled={busy||!paymentForm.date||!/^[A-Za-z0-9/_-]{6,64}$/.test(paymentForm.transactionId)||!Number.isFinite(Number(paymentForm.amount))||Number(paymentForm.amount)<=0} onClick={()=>void perform(async()=>{await callBankSetuWorker('/license-request-change',{kind:state?.license?.plan==='annual'&&requestPlan==='annual'?'renewal':'upgrade',plan:requestPlan,requestId:crypto.randomUUID(),paidPaise:Math.round(Number(paymentForm.amount)*100),paymentDate:paymentForm.date,transactionId:paymentForm.transactionId});setRequestPlan(null);setPaymentForm({amount:'',date:'',transactionId:''});},'Request sent for Master Admin payment review.')}>Submit Request</button>{error&&<p role="alert">{error}</p>}</section></div>}
